DESCRIBE production_transactions;
SELECT COUNT(*) AS total_rows FROM products p INNER JOIN production_transactions pt ON p.Product_ID = pt.Product_ID;
SELECT 
	p.product_name, 
    sum(pt.Produced_Quantity) AS total_production 
    FROM products p 
    INNER JOIN production_transactions pt 
    ON p.product_id = pt.product_id 
    GROUP BY p.Product_Name 
    ORDER BY total_production DESC;
    SELECT
        p.product_name, 
		pt.produced_quantity
	FROM products p
    LEFT JOIN production_transactions pt
    ON p.Product_ID = pt.Product_ID;
    SELECT COUNT(*) AS total_row FROM products p LEFT JOIN production_transactions pt ON p.product_id = pt.product_id;
    SELECT p.product_name, pt.produced_quantity FROM products p RIGHT JOIN production_transactions pt ON p.Product_ID = pt.Product_ID;
    SELECT count(*) AS total_row FROM products p RIGHT JOIN production_transactions pt ON p.Product_ID = pt.Product_ID;
    SELECT 
		p.product_name,
        s.supplier_name,
        pt.purchase_quantity
    FROM purchase_transactions pt
    INNER JOIN products p
	ON pt.product_id = p.product_id
    INNER JOIN suppliers s
    ON pt.Supplier_ID = s.Supplier_ID;
DESC raw_materials;    
SELECT 
    rm.material_name,
    s.supplier_name,
    pt. purchase_quantity
FROM purchase_transactions pt
INNER JOIN raw_materials rm
ON pt.Material_ID = rm.Material_ID
INNER JOIN suppliers s 
ON pt.Supplier_ID = s.Supplier_ID;    
SELECT count(*) AS total_row FROM purchase_transactions pt INNER JOIN raw_materials rm ON pt.Material_ID = rm.Material_ID INNER JOIN suppliers s ON pt.Supplier_ID = s.Supplier_ID;
SELECT 
    CASE 
       WHEN purchase_quantity >= 1000 THEN 'high purchase'
       WHEN purchase_quantity >= 500 THEN 'medium purchase'
       ELSE 'low purchase'
END AS purchase_category, 
COUNT(*) AS total_transactions
FROM purchase_transactions
GROUP BY 
    CASE 
       WHEN Purchase_Quantity >= 1000 THEN 'high purchase'
       WHEN Purchase_Quantity >= 500 THEN 'medium purchase'
       ELSE 'low purchase' 
END;       
SELECT 
	CASE 
       WHEN purchase_quantity >= 1000 THEN 'high purchase'
       WHEN purchase_quantity >= 500 THEN 'medium purchase'
       ELSE 'low purchase'
END AS purchase_category,
COUNT(*) AS total_transactions,
SUM(purchase_quantity * unit_cost * (1 - discount_percent / 100) * (1 + gst_percent / 100)) AS total_purchase_cost
FROM purchase_transactions
GROUP BY 
    CASE 
       WHEN purchase_quantity >= 1000 THEN 'high purchase'
       WHEN purchase_quantity >= 500 THEN 'medium purchase'
       ELSE 'low purchase'
END;
SELECT
    s.supplier_name,
    sum(pt.Purchase_Quantity) AS Total_Purchase_Quantity

FROM purchase_transactions pt

INNER JOIN suppliers s
ON pt.Supplier_ID = s.Supplier_ID

GROUP BY s.Supplier_Name;
SELECT
    Product_Name,
    Unit_Price
FROM products
WHERE Unit_Price = (
      SELECT MAX(Unit_Price)
      FROM products
);      
SELECT
    product_name,
    unit_price
FROM products
WHERE Unit_Price > (
       SELECT AVG(Unit_Price)
       FROM products
); 
SELECT 
     product_name
FROM products
WHERE Product_ID IN (
	SELECT Product_ID
    FROM bill_of_materials
);    
SELECT
	DENSE_RANK() OVER (ORDER BY Unit_Price DESC) AS dense_rank_num,
    product_name,
    unit_price
FROM products;    
WITH AvgPrice AS
(
    SELECT AVG(unit_price) AS avg_unit_price
    FROM products
)
SELECT 
   product_name,
   unit_price
FROM products
WHERE Unit_Price >
(
	SELECT avg_unit_price
    FROM AvgPrice
);    
SELECT * 
FROM highpriceproducts;
SELECT
    s.Supplier_Name,
    sum(pt.purchase_quantity * pt.unit_cost * (1 - pt.discount_percent / 100) * (1 + pt.gst_percent / 100)) AS Total_Purchase_Value
FROM purchase_transactions pt

INNER JOIN suppliers s
ON pt.Supplier_ID = s.Supplier_ID
 
GROUP BY s.Supplier_Name

ORDER BY total_purchase_value DESC

LIMIT 5;
