DELIMITER //

CREATE PROCEDURE ShowProducts()
BEGIN

SELECT
    Product_Name,
    Unit_Price
FROM products;

END //

DELIMITER ;
CALL ShowProducts();
DELIMITER //

CREATE PROCEDURE ShowProductsAbovePrice
(
    IN MinPrice DECIMAL(10,2)
)
BEGIN

SELECT
    Product_Name,
    Unit_Price
FROM products
WHERE Unit_Price > MinPrice;

END //

DELIMITER ;
CALL ShowProductsAbovePrice(5000);
DELIMITER //

CREATE FUNCTION DoublePrice(price DECIMAL(10,2))
RETURNS DECIMAL(10,2)

DETERMINISTIC

BEGIN

RETURN price * 2;

END //

DELIMITER ;
SELECT DoublePrice(3500);
SELECT
    Product_Name,
    Unit_Price,
    DoublePrice(Unit_Price) AS Double_Unit_Price
FROM products;
CREATE TABLE Product_Audit
(
    Audit_ID INT AUTO_INCREMENT PRIMARY KEY,
    Product_Name VARCHAR(100),
    Action_Time DATETIME
);
DELIMITER //

CREATE TRIGGER trg_Product_Insert

AFTER INSERT
ON products

FOR EACH ROW

BEGIN

INSERT INTO Product_Audit
(
    Product_Name,
    Action_Time
)

VALUES
(
    NEW.Product_Name,
    NOW()
);

END //

