DELIMITER //
CREATE TRIGGER trg_check_unit_price

BEFORE INSERT
ON products

FOR EACH ROW

BEGIN

IF NEW.unit_price <= 0 THEN

SIGNAL SQLSTATE '45000'
SET MESSAGE_TEXT = 'unit price must be greater than 0';

END IF;
END //
DELIMITER ; 

