CREATE TABLE product_price_audit
(
  audit_id INT AUTO_INCREMENT PRIMARY KEY,
  product_id TEXT,
  product_name TEXT,
  old_price INT,
  new_price INT,
  updated_time DATETIME
);  
DELIMITER //
CREATE TRIGGER trg_product_price_update

AFTER UPDATE
ON products

FOR EACH ROW 

BEGIN

INSERT INTO product_price_audit
(
  product_id,
  product_name,
  old_price,
  new_price,
  updated_time
)
VALUE
(
    NEW.product_id,
    NEW.product_name,
    OLD.unit_price,
    NEW.unit_price,
    NOW()
);

END //
DELIMITER ;    
  
