CREATE TABLE purchase_transactions
(
  purchase_id VARCHAR(10) PRIMARY KEY,
  supplier_id VARCHAR(10) NOT NULL,
  material_id VARCHAR(10) NOT NULL,
  purchase_date DATE NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  total_amount DECIMAL(10,2) NOT NULL,
  
  CONSTRAINT fk_purchase_supplier
  FOREIGN KEY (supplier_id)
  REFERENCES suppliers(supplier_id),
   
  CONSTRAINT fk_purchase_material
  FOREIGN KEY (material_ID)
  REFERENCES raw_materials(material_id)
);  
  
DESCRIBE purchase_transactions;
CREATE TABLE production_transactions
(
    production_id VARCHAR(10) PRIMARY KEY,
    product_id VARCHAR(10) NOT NULL,
    production_date DATE NOT NULL,
    quantity_produced INT NOT NULL,
    rejected_quantity INT NOT NULL,

    CONSTRAINT fk_production_product
    FOREIGN KEY (product_id)
    REFERENCES products(product_id)
);
DESCRIBE production_transactions;
CREATE TABLE inventory_transactions
(
    transaction_id VARCHAR(10) PRIMARY KEY,
    material_id VARCHAR(10) NOT NULL,
    transaction_date DATE NOT NULL,
    transaction_type VARCHAR(20) NOT NULL,
    quantity INT NOT NULL,
    balance_stock INT NOT NULL,

    CONSTRAINT fk_inventory_material
    FOREIGN KEY (material_id)
    REFERENCES raw_materials(material_id)
);
DESCRIBE inventory_transactions;
