-- Verification query:
SELECT COUNT(*) AS Total_Production
FROM production_transactions;
DESCRIBE inventory_transactions;
DROP TABLE inventory_transactions;
CREATE TABLE inventory_transactions (
    inventory_transaction_id VARCHAR(15) PRIMARY KEY,
    transaction_date DATE NOT NULL,
    material_id VARCHAR(10) NOT NULL,
    transaction_type VARCHAR(20) NOT NULL,
    quantity INT NOT NULL,
    warehouse VARCHAR(50) NOT NULL,
    reference_id VARCHAR(20) NOT NULL,

    CONSTRAINT fk_inventory_material
        FOREIGN KEY (material_id)
        REFERENCES raw_materials(material_id)
);
DESCRIBE inventory_transactions;

USE manufacturing_inventory_v3;

START TRANSACTION;

