DESCRIBE bom;
SHOW TABLES;
CREATE TABLE bom (
    bom_id VARCHAR(10) PRIMARY KEY,
    product_id VARCHAR(10) NOT NULL,
    material_id VARCHAR(10) NOT NULL,
    quantity_required DECIMAL(10,2) NOT NULL,
    wastage_percent DECIMAL(5,2) DEFAULT 0,
    effective_from DATE NOT NULL,
    bom_status VARCHAR(20) NOT NULL,

    CONSTRAINT fk_bom_product
        FOREIGN KEY (product_id)
        REFERENCES products(product_id),

    CONSTRAINT fk_bom_material
        FOREIGN KEY (material_id)
        REFERENCES raw_materials(material_id)
);
DESCRIBE bom;

USE manufacturing_inventory_v3;

START TRANSACTION;

