SELECT COUNT(*) AS Total_BOM FROM bom;

SELECT 'products' AS Table_Name, COUNT(*) AS Records FROM products
UNION ALL
SELECT 'suppliers', COUNT(*) FROM suppliers
UNION ALL
SELECT 'raw_materials', COUNT(*) FROM raw_materials
UNION ALL
