SELECT purchase_id, COUNT(*)
FROM purchase_transactions
GROUP BY purchase_id
HAVING COUNT(*) > 1;

SELECT production_id, COUNT(*)
FROM production_transactions
GROUP BY production_id
HAVING COUNT(*) > 1;

SELECT inventory_transaction_id, COUNT(*)
FROM inventory_transactions
GROUP BY inventory_transaction_id
HAVING COUNT(*) > 1;

SELECT bom_id, COUNT(*)
FROM bom
GROUP BY bom_id
HAVING COUNT(*) > 1;

