SELECT
(SELECT COUNT(*) FROM products) Products,
(SELECT COUNT(*) FROM suppliers) Suppliers,
(SELECT COUNT(*) FROM raw_materials) Raw_Materials,
(SELECT COUNT(*) FROM purchase_transactions) Purchases,
(SELECT COUNT(*) FROM production_transactions) Production,
(SELECT COUNT(*) FROM inventory_transactions) Inventory,
(SELECT COUNT(*) FROM bom) BOM;SELECT
(SELECT COUNT(*) FROM products) Products,
(SELECT COUNT(*) FROM suppliers) Suppliers,
(SELECT COUNT(*) FROM raw_materials) Raw_Materials,
(SELECT COUNT(*) FROM purchase_transactions) Purchases,
(SELECT COUNT(*) FROM production_transactions) Production,
(SELECT COUNT(*) FROM inventory_transactions) Inventory,
(SELECT COUNT(*) FROM bom) BOM;
SELECT *
FROM products;
SELECT
    product_id,
    product_name,
    unit_price
FROM products;
SELECT
    product_name,
    unit_price
FROM products
ORDER BY unit_price DESC
LIMIT 5;
SELECT
SUM(
purchase_quantity * unit_cost * (1 - discount_percent / 100) * (1 + gst_percent / 100)
)
AS Total_Purchase_Value
FROM purchase_transactions;
SELECT
s.supplier_name,
SUM(pt.purchase_quantity) AS Total_Qty
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id=s.supplier_id
GROUP BY s.supplier_name
ORDER BY Total_Qty DESC;
SELECT
p.product_name,
SUM(produced_quantity) AS Total_Produced
FROM production_transactions pr
JOIN products p
ON pr.product_id=p.product_id
GROUP BY p.product_name
ORDER BY Total_Produced DESC;
SELECT COUNT(*) AS Total_Products
FROM products;
SELECT
    product_category,
    COUNT(*) AS Total_Products
FROM products
GROUP BY product_category
ORDER BY Total_Products DESC;

SELECT
    product_name,
    product_category,
    unit_price
FROM products
ORDER BY unit_price DESC
LIMIT 5;
SELECT
    product_name,
    unit_price
FROM products
ORDER BY unit_price ASC
LIMIT 5;

SELECT
    product_category,
    ROUND(AVG(unit_price), 2) AS Average_Price
FROM products
GROUP BY product_category
ORDER BY Average_Price DESC;

-- Query 1: Total Number of Products

SELECT COUNT(*) AS Total_Products
FROM products;

-- Query 6: Total Number of Suppliers

SELECT COUNT(*) AS Total_Suppliers
FROM suppliers;

-- Query 7: Supplier Wise Purchase Quantity

SELECT
    s.supplier_name,
    SUM(pt.purchase_quantity) AS Total_Purchase_Qty
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id = s.supplier_id
GROUP BY s.supplier_name
ORDER BY Total_Purchase_Qty DESC;

-- Query 8: Supplier Wise Purchase Value

SELECT
    s.supplier_name,
    ROUND(SUM(pt.purchase_quantity * pt.unit_cost * (1 - pt.discount_percent / 100) * (1 + pt.gst_percent / 100)), 2) AS Total_Purchase_Value
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id = s.supplier_id
GROUP BY s.supplier_name
ORDER BY Total_Purchase_Value DESC;

-- Query 9: Top 5 Suppliers

SELECT
    s.supplier_name,
    ROUND(SUM(pt.purchase_quantity * pt.unit_cost * (1 - pt.discount_percent / 100) * (1 + pt.gst_percent / 100)), 2) AS Total_Purchase_Value
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id = s.supplier_id
GROUP BY s.supplier_name
ORDER BY Total_Purchase_Value DESC
LIMIT 5;

-- Query 10: Average Unit Cost by Supplier

SELECT
    s.supplier_name,
    ROUND(AVG(pt.unit_cost), 2) AS Average_Unit_Cost
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id = s.supplier_id
GROUP BY s.supplier_name
ORDER BY Average_Unit_Cost DESC;

-- Query 11: Total Purchase Value

SELECT
ROUND(SUM(purchase_quantity * unit_cost * (1 - discount_percent / 100) * (1 + gst_percent / 100)),2) AS Total_Purchase_Value
FROM purchase_transactions;

-- Query 12: Monthly Purchase Value

SELECT
MONTHNAME(purchase_date) AS Month,
ROUND(SUM(purchase_quantity * unit_cost * (1 - discount_percent / 100) * (1 + gst_percent / 100)),2) AS Purchase_Value
FROM purchase_transactions
GROUP BY MONTHNAME(purchase_date),
MONTH(purchase_date)
ORDER BY MONTH(purchase_date);

-- Query 13: Material Wise Purchase Quantity

SELECT
rm.material_name,
SUM(pt.purchase_quantity) AS Total_Qty
FROM purchase_transactions pt
JOIN raw_materials rm
ON pt.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Total_Qty DESC;

-- Query 14: Material Wise Purchase Value

SELECT
rm.material_name,
ROUND(SUM(pt.purchase_quantity * pt.unit_cost * (1 - pt.discount_percent / 100) * (1 + pt.gst_percent / 100)),2) AS Purchase_Value
FROM purchase_transactions pt
JOIN raw_materials rm
ON pt.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Purchase_Value DESC;

-- Query 15: Top 5 Most Purchased Materials

SELECT
rm.material_name,
SUM(pt.purchase_quantity) AS Total_Qty
FROM purchase_transactions pt
JOIN raw_materials rm
ON pt.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Total_Qty DESC
LIMIT 5;

-- Query 16: Product Wise Production

SELECT
    p.product_name,
    SUM(pt.produced_quantity) AS Total_Produced
FROM production_transactions pt
JOIN products p
ON pt.product_id = p.product_id
GROUP BY p.product_name
ORDER BY Total_Produced DESC;

-- Query 17: Monthly Production

SELECT
    MONTHNAME(production_date) AS Month,
    SUM(produced_quantity) AS Total_Production
FROM production_transactions
GROUP BY MONTHNAME(production_date),
MONTH(production_date)
ORDER BY MONTH(production_date);

-- Query 18: Shift Wise Production

SELECT
    shift,
    SUM(produced_quantity) AS Total_Production
FROM production_transactions
GROUP BY shift
ORDER BY Total_Production DESC;

-- Query 19: Production Line Wise Output

SELECT
    production_line,
    SUM(produced_quantity) AS Total_Output
FROM production_transactions
GROUP BY production_line
ORDER BY Total_Output DESC;

-- Query 20: Product Wise Rejection

SELECT
    p.product_name,
    SUM(pt.rejected_quantity) AS Total_Rejected
FROM production_transactions pt
JOIN products p
ON pt.product_id = p.product_id
GROUP BY p.product_name
ORDER BY Total_Rejected DESC;

-- Query 21: Total Inventory Quantity

SELECT
SUM(quantity) AS Total_Inventory
FROM inventory_transactions;

-- Query 22: Material Wise Inventory

SELECT
rm.material_name,
SUM(it.quantity) AS Total_Quantity
FROM inventory_transactions it
JOIN raw_materials rm
ON it.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Total_Quantity DESC;

-- Query 23: Transaction Type Wise Quantity

SELECT
transaction_type,
SUM(quantity) AS Total_Quantity
FROM inventory_transactions
GROUP BY transaction_type
ORDER BY Total_Quantity DESC;

-- Query 24: Warehouse Wise Quantity

SELECT
warehouse,
SUM(quantity) AS Total_Quantity
FROM inventory_transactions
GROUP BY warehouse
ORDER BY Total_Quantity DESC;

-- Query 25: Material Wise Transaction Count

SELECT
rm.material_name,
COUNT(*) AS Total_Transactions
FROM inventory_transactions it
JOIN raw_materials rm
ON it.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Total_Transactions DESC;

DESC bom;
-- Query 26: Product Wise BOM Count

SELECT
    p.product_name,
    COUNT(*) AS Total_Materials
FROM bom b
JOIN products p
ON b.product_id = p.product_id
GROUP BY p.product_name
ORDER BY Total_Materials DESC;

-- Query 27: Total Quantity Required by Product

SELECT
    p.product_name,
    ROUND(SUM(b.quantity_required),2) AS Total_Quantity_Required
FROM bom b
JOIN products p
ON b.product_id = p.product_id
GROUP BY p.product_name
ORDER BY Total_Quantity_Required DESC;

-- Query 28: Material Usage Count

SELECT
    rm.material_name,
    COUNT(*) AS Usage_Count
FROM bom b
JOIN raw_materials rm
ON b.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Usage_Count DESC;

-- Query 29: Average Wastage Percentage

SELECT
ROUND(AVG(wastage_percent),2) AS Average_Wastage
FROM bom;

-- Query 30: BOM Status Summary

SELECT
    bom_status,
    COUNT(*) AS Total_Records
FROM bom
GROUP BY bom_status
ORDER BY Total_Records DESC;

-- Query 31: Top 5 Highest Value Products

SELECT
    product_name,
    unit_price
FROM products
ORDER BY unit_price DESC
LIMIT 5;

-- Query 32: Supplier Performance

SELECT
    s.supplier_name,
    COUNT(*) AS Total_Purchases
FROM purchase_transactions pt
JOIN suppliers s
ON pt.supplier_id = s.supplier_id
GROUP BY s.supplier_name
ORDER BY Total_Purchases DESC;

-- Query 33: Monthly Production Records

SELECT
MONTHNAME(production_date) AS Month,
COUNT(*) AS Total_Production_Transactions
FROM production_transactions
GROUP BY MONTHNAME(production_date),
MONTH(production_date)
ORDER BY MONTH(production_date);

-- Query 34: Most Frequently Used Raw Materials

SELECT
rm.material_name,
COUNT(*) AS Usage_Count
FROM bom b
JOIN raw_materials rm
ON b.material_id = rm.material_id
GROUP BY rm.material_name
ORDER BY Usage_Count DESC
LIMIT 10;

-- Query 35: Active BOM Summary

SELECT
bom_status,
COUNT(*) AS Total
FROM bom
GROUP BY bom_status;
